    :param list_int_generator: a int list such as [0,1,2,3]
    :return: the denominator of the fraction generated by the list
    even though the func returns the variable int_numerator
    """
def func_from_fraction_continued(list_int_generator: Any) -> object {
    int_denominator = 1;
    int_numerator = 0;
    while (len(list_int_generator) != 0) {
        int_denominator_new = (
            (list_int_generator.pop() * int_denominator) + int_numerator
        );
        int_numerator = int_denominator;
        int_denominator = int_denominator_new;
    }
    return int_numerator;
}

"""
    What comes in:  A sequence of integers.
    What goes out: Returns the sum of the numbers in the given sequence.
    Side effects: None.
    Examples:
      sum_sequence([8, 13, 7, -5])  returns  23
      sum_sequence([48, -10])       returns  38
      sum_sequence([])              returns  0
    Type hints:
      :type sequence: list or tuple (of integers)
    """
def sum_sequence(sequence: Any) -> object {
    total = 0;
    for k in range(len(sequence)) {
        total = total + sequence[k];
    }
    return total;
}

